INSERT INTO `wp_church_admin_calendar_date` VALUES ('Open Minds, Open Books, Book Club','UN-BOOK CLUB / Emerson\'s \"Open Minds Open Books\" Wednesday, April 5, 2023 at 6:30 pm 122 N. 5th Street, St. Charles Emerson\'s Un-Book Club (\"Open Minds Open Books\") will be meeting on Wed., 4/5/2023 at 6:30 pm. ALL ARE WELCOME! (You don\'t have to attend Emerson to attend.) If you intend to attend, please leave your tweed, leather elbow patches, scotch, and pipe at home! There is no \"assigned book\". Rather, we talk about books that changed us or made us ponder, or talk about books we are reading now.. It is an eclectic group, and the conversation is sometimes lively. It is not \"churchy\", but it IS \"booky\". (I hope to attend myself, but I am still working out scheduling conflicts. Whether or not I am eventually able to attend myself, you should consider attending yourself.)','',1,NULL,'2023-04-05','18:30:00',NULL,'20:30:00',NULL,16,NULL,NULL,NULL,NULL,1,30,5912,1,NULL,'n13',NULL,'calendar',0),('Happy Hour','Eat, Drink, and Be Merry with friends...','Zoom',1,NULL,'2023-03-23','19:00:00',NULL,'20:00:00',NULL,14,NULL,NULL,NULL,NULL,1,1,5910,1,NULL,'1',NULL,'calendar',0),('Emerson Community Writing Group','Program facilitator Karyl Howard says the next \"exercise\" I\'m going to suggest that you make a list of 100 things you\'d like to write about. If you find yourself repeating ideas on your list, just keep going. We\'ll talk about that!\r\n\r\nContact Karyl Howard with questions.',NULL,1,NULL,'2023-03-19','12:00:00',NULL,'02:00:00',NULL,15,NULL,NULL,NULL,NULL,1,1,5911,0,NULL,'s',NULL,'calendar',0),('Open Minds, Open Books, Book Club','UN-BOOK CLUB / Emerson\'s \"Open Minds Open Books\" Wednesday, April 5, 2023 at 6:30 pm 122 N. 5th Street, St. Charles Emerson\'s Un-Book Club (\"Open Minds Open Books\") will be meeting on Wed., 4/5/2023 at 6:30 pm. ALL ARE WELCOME! (You don\'t have to attend Emerson to attend.) If you intend to attend, please leave your tweed, leather el